@Component("distributor-handler")
@ProcessingGroup("distributor-processing-group")
public class DistributorEventHandler {
	
	// core constructor
	DistributorEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateDistributorEvent
     */
    @EventHandler
    public void handle( CreateDistributorEvent event) {
        entityManager.persist(new Distributor(event.getDistributorId(), event.getName(), event.getLicenseNumber(), event.getRegion(), event.getInsurers(), event.getAgents(), event.getPolicies(), event.getDistributorType()));
    }

    /*
     * @param	event UpdateDistributorEvent
     */
    @EventHandler
    public Distributor handle( UpdateDistributorEvent event) {
    	entityManager.merge(new Distributor(event.getDistributorId(), event.getName(), event.getLicenseNumber(), event.getRegion(), event.getInsurers(), event.getAgents(), event.getPolicies(), event.getDistributorType()));
    }
    
    /*
     * @param	event DeleteDistributorEvent
     */
    @EventHandler
    public void on( DeleteDistributorEvent event) {
    	Distributor entity = new Distributor();
   
    	// ------------------------------------------
    	// apply the DistributorId
    	// ------------------------------------------
    	entity.setDistributorId( event.getDistributorId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final DistributorRepository distributorEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(DistributorEventHandler.class.getName());

}
